      dose: { start: 0.5, step: 0.25, interval: '5 min', usual: '0.5–3', max: 9, ceiling: 'Non-weight-based orders: 10–200 mcg/min. Bolus 50–200 mcg (push-dose 100 mcg) for transient hypotension.' },
      onset: '1 min; t½ 5 min', ind: ['Hypotension with tachyarrhythmia where β-stimulation would be harmful (fast AF), hypertrophic obstructive cardiomyopathy or aortic stenosis with hypotension (preserve afterload, avoid inotropy)', 'Procedural / peri-intubation hypotension (push dose), neuraxial anaesthesia', 'Salvage when norepinephrine causes intolerable arrhythmia, or high-output vasoplegia'],
